#include "sblr_project_coordinator.hpp"
#include "api_diagnostics.hpp"
#include <algorithm>
#include <map>
#include <mutex>
namespace scratchbird::engine::internal_api { namespace {std::mutex mutex;std::map<std::string,scratchbird::engine::sblr::SblrProjectDescriptorV1> live,used;std::string key(const scratchbird::engine::sblr::ProjectSha&h){return{reinterpret_cast<const char*>(h.data()),h.size()};}bool tag(const EngineRequestContext&c,const char*s){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),s)!=c.trace_tags.end();}EngineApiDiagnostic diag(std::string c,std::string d){return MakeEngineApiDiagnostic(std::move(c),std::move(d),{});}}
SblrProjectCoordinationResult CompileSblrProjectDescriptor(const EngineRequestContext&c,const std::string&r,uint64_t occurrence,uint32_t projection,uint64_t availability){std::lock_guard lock(mutex);SblrProjectCoordinationResult out;if(!tag(c,"private_project_binder")||!c.statement_metadata_snapshot_engine_owned||r!=c.statement_uuid.canonical||!occurrence||!projection||!availability){out.diagnostic=diag("SBLR.OPERAND_INVALID","sblr.project.coordination_invalid");return out;}out.descriptor.body[0]=1;out.descriptor.body[1]=uint8_t(occurrence);out.descriptor.body[2]=uint8_t(projection);out.descriptor.availability=availability;auto bytes=scratchbird::engine::sblr::EncodeSblrProjectDescriptorV1(out.descriptor,false);if(!scratchbird::engine::sblr::DecodeSblrProjectDescriptorV1(bytes.data(),bytes.size(),&out.descriptor,nullptr,false)){out.diagnostic=diag("SBLR.OPERAND_INVALID","sblr.project.descriptor_invalid");return out;}live[key(out.descriptor.evidence)]=out.descriptor;out.ok=true;out.diagnostic=diag("OK","ok");return out;}
SblrProjectCoordinationResult ConsumeSblrProjectDescriptor(const EngineRequestContext&c,const scratchbird::engine::sblr::SblrProjectDescriptorV1&v){std::lock_guard lock(mutex);SblrProjectCoordinationResult out;auto k=key(v.evidence);auto it=live.find(k);if(!tag(c,"private_project")){out.diagnostic=diag("SECURITY.ACCESS_DENIED","sblr.project.hidden");return out;}if(it==live.end()){out.diagnostic=used.count(k)?diag("MGA.TRANSACTION.STALE","sblr.project.stale"):diag("SECURITY.ACCESS_DENIED","sblr.project.hidden");return out;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){out.diagnostic=diag("PROCESS.CANCELLED","sblr.project.cancelled");return out;}used[k]=v;live.erase(it);out.ok=true;out.descriptor=v;out.diagnostic=diag("OK","ok");return out;}}
